package org.tangowiz.wear
import android.Manifest
import android.app.Activity
import android.content.Intent
import android.content.pm.PackageManager
import android.graphics.Color
import android.graphics.drawable.GradientDrawable
import android.os.*
import android.view.*
import android.widget.*
import org.json.JSONObject

class WatchActivity:Activity(){
 private lateinit var body:LinearLayout;private lateinit var scroll:ScrollView;private var visible=false;private var fresh=false;private var wantCapture=false;private var captureRequested=false;private var historyOnly=false;private var controlConsumed=false;private val handler=Handler(Looper.getMainLooper());private val changed:()->Unit={runOnUiThread{if(visible){render();maybeCapture()}}};private val ticker=object:Runnable{override fun run(){if(visible){WatchCache.changed();handler.postDelayed(this,10000)}}}
 private fun dp(n:Int)=(n*resources.displayMetrics.density).toInt()
 override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);WatchCache.init(this);controlConsumed=savedInstanceState?.getBoolean("control_consumed")?:false;historyOnly=savedInstanceState?.getBoolean("history_only")?:false;captureRequested=savedInstanceState?.getBoolean("capture_requested")?:false;wantCapture=intent.getBooleanExtra("requestCapture",false)||WatchCache.pendingCapture;scroll=ScrollView(this);body=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER_HORIZONTAL;setPadding(dp(26),dp(38),dp(26),dp(42));setBackgroundColor(Color.BLACK)};scroll.addView(body);setContentView(scroll);window.decorView.isFocusableInTouchMode=true;window.decorView.requestFocus();window.decorView.setOnGenericMotionListener{_,event->if(event.action==MotionEvent.ACTION_SCROLL){scroll.smoothScrollBy(0,(-event.getAxisValue(MotionEvent.AXIS_SCROLL)*dp(36)).toInt());true}else false}}
 override fun onStart(){super.onStart();visible=true;WatchCache.listeners.add(changed);fresh=false;render();refreshCapture();consumeControl();handler.post(ticker)}
 override fun onStop(){visible=false;WatchCache.listeners.remove(changed);handler.removeCallbacks(ticker);super.onStop()}
 override fun onNewIntent(value:Intent){super.onNewIntent(value);intent=value;if(value.getBooleanExtra("requestCapture",false)){wantCapture=true;captureRequested=false;fresh=false;refreshCapture()};controlConsumed=false;consumeControl()}
 override fun onSaveInstanceState(out:Bundle){out.putBoolean("control_consumed",controlConsumed);out.putBoolean("history_only",historyOnly);out.putBoolean("capture_requested",captureRequested);super.onSaveInstanceState(out)}
 private fun consumeControl(){if(controlConsumed)return;controlConsumed=true;when(intent.getStringExtra("control")){"toggle"->{val start=!WatchCache.state.optBoolean("listening");wantCapture=start&&WatchCache.state.optString("microphone")=="watch";WatchLink.set(JSONObject().put("listening",start))};"microphone"->{val watch=WatchCache.state.optString("microphone")!="watch";wantCapture=watch&&WatchCache.state.optBoolean("listening");WatchLink.set(JSONObject().put("microphone",if(watch)"watch" else "phone"))};"history"->{historyOnly=true;WatchLink.history()}};render()}
 override fun onBackPressed(){if(historyOnly){historyOnly=false;render()}else super.onBackPressed()}
 private fun showHistory(){val history=WatchCache.history;for(n in history.length()-1 downTo maxOf(0,history.length()-100)){val r=history.optJSONObject(n)?:continue;val time=runCatching{java.time.format.DateTimeFormatter.ofPattern("HH:mm").withZone(java.time.ZoneId.systemDefault()).format(java.time.Instant.parse(r.optString("time")))}.getOrDefault("");label(listOf((time+"  "+r.optString("orchestra")).trim(),r.optString("title"),r.optString("singer"),r.optString("year")).filter{it.isNotBlank()}.joinToString("\n"),15f,5)}}
 private fun label(text:String,size:Float=16f,lines:Int=0){body.addView(TextView(this).apply{this.text=if(text.contains(" ?"))"? "+text.removeSuffix(" ?") else text;textSize=size;setTextColor(Color.WHITE);gravity=Gravity.CENTER;setPadding(0,dp(5),0,dp(5));contentDescription=text;if(lines>0){maxLines=lines;ellipsize=android.text.TextUtils.TruncateAt.END;setOnClickListener{val full=TextView(this@WatchActivity).apply{this.text=text;setTextColor(Color.WHITE);setPadding(dp(18),dp(16),dp(18),dp(16));textSize=18f};android.app.AlertDialog.Builder(this@WatchActivity).setView(ScrollView(this@WatchActivity).apply{addView(full)}).setPositiveButton("Close",null).show()}}},LinearLayout.LayoutParams(-1,-2))}
 private fun button(text:String,hint:String,action:()->Unit){body.addView(Button(this).apply{this.text=text;contentDescription=hint;textSize=17f;setTextColor(Color.WHITE);background=GradientDrawable().apply{setColor(Color.rgb(33,83,67));cornerRadius=dp(24).toFloat()};setOnClickListener{action()}},LinearLayout.LayoutParams(-1,dp(52)).apply{topMargin=dp(7)})}
 private fun render(){val position=scroll.scrollY;body.removeAllViews();if(historyOnly){label("☷",24f);button("↻","Refresh history"){WatchLink.history()};showHistory();scroll.post{scroll.scrollTo(0,position)};return};val state=WatchCache.state;val best=state.optJSONObject("best");body.addView(OrchestraNameView(this).apply{normalMaxSp=25;keywordMaxSp=34;contextMaxSp=22;setTextColor(Color.WHITE);setOnClickListener{WatchLink.reset()};showName(WatchCache.orchestra(),WatchCache.keyword())},LinearLayout.LayoutParams(-1,dp(76)));label(WatchCache.song(),18f,3);if(best!=null)label("${best.optInt("percent")}%",18f)
  val status=when{WatchCache.pending.isNotEmpty()->WatchCache.pending;WatchCache.error.isNotEmpty()->WatchCache.error;state.optString("error").isNotEmpty()->state.optString("error");WatchCache.capturing->"Watch microphone · streaming";!WatchCache.connected->"Disconnected · cached";!state.optBoolean("ready")&&state.optBoolean("listening")->state.optString("phase","Starting…");WatchCache.stale()->"Cached result";else->state.optString("phase","")};if(status.isNotBlank())label(status,13f,3)
  button("⛶","Ambient display"){startActivity(Intent(this,AmbientDisplayActivity::class.java))}
  button(if(state.optBoolean("listening"))"Ⅱ" else "▶",if(state.optBoolean("listening"))"Pause identification" else "Start identification"){val start=!WatchCache.state.optBoolean("listening");wantCapture=start&&WatchCache.state.optString("microphone")=="watch";captureRequested=false;if(!start)stopService(Intent(this,WatchMicService::class.java));WatchLink.set(JSONObject().put("listening",start))}
  button(if(state.optString("microphone")=="watch")"⌚  Watch" else "▣  Phone","Select microphone"){val watch=WatchCache.state.optString("microphone")!="watch";wantCapture=watch&&WatchCache.state.optBoolean("listening");captureRequested=false;if(!watch)stopService(Intent(this,WatchMicService::class.java));WatchLink.set(JSONObject().put("microphone",if(watch)"watch" else "phone"))}
  button("●  ${if(state.optBoolean("audio"))"On" else "Off"}","Save audio"){WatchLink.set(JSONObject().put("audio",!WatchCache.state.optBoolean("audio")))}
  button("🐞  ${if(state.optBoolean("timing"))"On" else "Off"}","Timing debug"){WatchLink.set(JSONObject().put("timing",!WatchCache.state.optBoolean("timing")))}
  val intervals=listOf(2000L,5000L,10000L,30000L,60000L);button("↻  ${state.optLong("updateIntervalMs",5000)/1000}s","Result update interval"){val current=WatchCache.state.optLong("updateIntervalMs",5000);WatchLink.set(JSONObject().put("updateIntervalMs",intervals[(intervals.indexOf(current)+1).mod(intervals.size)]))}
  button("☷","History"){historyOnly=true;WatchLink.history();render()};scroll.post{scroll.scrollTo(0,position)}
 }
 private fun refreshCapture(){WatchLink.refresh{ok->runOnUiThread{fresh=ok;if(ok&&(!WatchCache.state.optBoolean("listening")||WatchCache.state.optString("microphone")!="watch")){WatchCache.pendingCapture=false;if(!WatchCache.pending.isNotEmpty())wantCapture=false};maybeCapture()}}}
 private fun maybeCapture(){if(!visible||!fresh||!wantCapture||captureRequested)return;val s=WatchCache.state;if(!s.optBoolean("listening")||s.optString("microphone")!="watch")return
  if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){captureRequested=true;requestPermissions(arrayOf(Manifest.permission.RECORD_AUDIO),42);return};if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){captureRequested=true;requestPermissions(arrayOf(Manifest.permission.POST_NOTIFICATIONS),43);return};captureRequested=true;getSystemService(android.app.NotificationManager::class.java).cancel(11);try{startForegroundService(Intent(this,WatchMicService::class.java));if(DisplaySession.enabled(this)&&intent.getBooleanExtra("requestCapture",false)){intent.removeExtra("requestCapture");startActivity(Intent(this,AmbientDisplayActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT))}}catch(e:Exception){WatchCache.error=e.message?:"Cannot start microphone";WatchCache.changed()}
 }
 override fun onRequestPermissionsResult(requestCode:Int,permissions:Array<out String>,grantResults:IntArray){super.onRequestPermissionsResult(requestCode,permissions,grantResults);captureRequested=false;if(grantResults.firstOrNull()==PackageManager.PERMISSION_GRANTED)maybeCapture()else{wantCapture=false;WatchCache.error="Microphone/notification permission is required";WatchCache.changed();WatchLink.status(false,WatchCache.error)}}
}
